---@class ActivityMidFestivalShopTool
local ActivityMidFestivalShopTool = {}

---转换活动商店数据
function ActivityMidFestivalShopTool.ConvertActivityStoreData(jsonData)
    local ret = {}
    ret.remainingTimes = jsonData.remainingTimes
    ret.products = {}
    for _, v in ipairs(jsonData.products) do
        local goodsList = CfUtils.Split(v.goodsId)
        local numList = CfUtils.Split(v.num)
        local rewards = {}

        for i = 1, #goodsList do
            local reward = {
                goodsId = goodsList[i],
                num = numList[i]
            }
            table.insert(rewards, reward)
        end

        ---@type MidFestivalProductDojo
        local product = MidFestivalProductDojo.New()
        product:Fill(v)
        product.rewards = rewards
        table.insert(ret.products, product)
    end
    return ret
end

function ActivityMidFestivalShopTool.ShopReq()
    ---@type ActivityMidFestivalComponent
    local activityComp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.ActivityMidFestivalComponent)

    local activityId = activityComp:GetActivityDojo().id
    local activityType = activityComp:GetActivityDojo().type

    local reqData = {
        activityUuid = activityId,
        activityType = activityType
    }
    GameUtils.Request(Interfaces.StoreActivityHome, reqData, function(request, response)
        if checkNumber(response.errCode) ~= 0 then
            return
        end
        local jsonData = response.data
        jsonData = ActivityMidFestivalShopTool.ConvertActivityStoreData(jsonData)
        activityComp:GetMallDojo():Fill(jsonData)
        Events.Broadcast(Constants.EventNames.ActivityMidFestivalMallReq)
    end)
end





return ActivityMidFestivalShopTool
